const PLANOS: Record<string, (c: Ctx) => React.ReactNode> = { cel: PCel, close: PClose, ots: POts, chegada: PChegada, aereo: PAereo, mesa: PMesa, relogio: PRelogio, visita: PVisita, texto: PTexto, extrato: PExtrato, cartao: PCartao, duplo: PDuplo, sonho: PSonho, fim: PFim };
const SEM_HUD = ['relogio', 'texto', 'extrato', 'fim', 'cartao'];

// ---------- vídeo ----------
export const BPVideo: React.FC<{ tempos: BPTempos; pasta?: string }> = ({ tempos }) => {
  const f = useCurrentFrame(); const t = f / 30; const total = Math.ceil(tempos.total * 30);
  const planos = React.useMemo(() => { const P: Plano[] = []; tempos.falas.forEach((fa) => { if (fa.s || !P.length) P.push({ i: P.length, ini: P.length ? Math.round(fa.t * 30) - 5 : 0, fim: 0, s: fa.s || { t: 'texto', txt: '' }, falas: [] }); P[P.length - 1].falas.push(fa); }); P.forEach((x, i) => { x.fim = i + 1 < P.length ? P[i + 1].ini : total; }); return P; }, [tempos]);
  let P = planos[0]; for (const x of planos) if (f >= x.ini) P = x;
  const lf = f - P.ini, dur = P.fim - P.ini; const fala = tempos.falas.find((x) => t >= x.t - 0.03 && t <= x.t + x.d);
  const ctx: Ctx = { f, lf, dur, s: P.s, v: P.i % 2 ? 1 : -1,
    p: (a, b, e = suave) => interpolate(lf, [0, dur], [a, b], { ...cl, easing: e }),
    pal: (w, d = 10) => { if (w) for (const fa of P.falas) { const i = fa.txt.toLowerCase().indexOf(w.toLowerCase()); if (i >= 0) return Math.round((fa.t + fa.d * (i / fa.txt.length)) * 30); } return P.ini + d; },
    nf: (k) => (P.falas[k] ? Math.round(P.falas[k].t * 30) : 1e9),
    boca: (q) => (fala?.q === q ? Math.min(1, (tempos.env[f] ?? 0) * 0.75 + (tempos.env[f + 1] ?? 0) * 0.25) : 0) };
  // extrato: último `hud` definido até aqui
  let alvo: number | null = null, ant: number | null = null, tq = 0;
  for (const fa of tempos.falas) { if (fa.t * 30 > f) break; if ('hud' in fa) { ant = alvo; alvo = fa.hud ?? null; tq = Math.round(fa.t * 30) + 8; } }
  const saldo = alvo == null ? null : ant == null ? alvo : conta(f, tq, ant, alvo);
  const hudK = alvo == null ? 0 : ant == null ? entra(f, tq, 12) : 1; const mudou = alvo != null && ant != null && f >= tq && f < tq + 40;
  const hudPulso = mudou ? Math.max(0, 1 - (f - tq - 24) / 14) * (f > tq + 22 ? 1 : 0.4 + 0.3 * Math.sin(f * 2.2)) : 0;
  return (
    <AbsoluteFill style={{ background: C.tinta }}>
      <svg viewBox="0 0 1920 1080" width={1920} height={1080}>
        <defs>
          <filter id="trem" x="-4%" y="-4%" width="108%" height="108%"><feTurbulence type="fractalNoise" baseFrequency="0.016" numOctaves={2} seed={Math.floor(f / 8)} result="n" /><feDisplacementMap in="SourceGraphic" in2="n" scale={5} xChannelSelector="R" yChannelSelector="G" /></filter>
          <filter id="fora" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation={7} /></filter>
          <filter id="grao"><feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves={1} seed={3} /><feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.45  0 0 0 0 0.4  0 0 0 0.07 0" /></filter>
          <radialGradient id="vinh" cx="50%" cy="50%" r="75%"><stop offset="0.55" stopColor="#000" stopOpacity={0} /><stop offset="1" stopColor="#000" stopOpacity={0.36} /></radialGradient>
          <radialGradient id="poca"><stop offset="0" stopColor="#FFE9A8" stopOpacity={0.5} /><stop offset="1" stopColor="#FFE9A8" stopOpacity={0} /></radialGradient>
          <radialGradient id="abajur"><stop offset="0" stopColor="#FFD98A" stopOpacity={0.5} /><stop offset="0.6" stopColor="#FFD98A" stopOpacity={0.12} /><stop offset="1" stopColor="#FFD98A" stopOpacity={0} /></radialGradient>
          <radialGradient id="tela"><stop offset="0" stopColor="#7FF0DD" stopOpacity={0.55} /><stop offset="1" stopColor="#7FF0DD" stopOpacity={0} /></radialGradient>
          <linearGradient id="ceuN" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor={C.noite} /><stop offset="1" stopColor="#33457A" /></linearGradient>
          <linearGradient id="parede" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#D8C7A2" /><stop offset="1" stopColor="#E8D9B8" /></linearGradient>
          <linearGradient id="sonhoG" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFB3C7" /><stop offset="0.6" stopColor="#FFD9A0" /><stop offset="1" stopColor="#FFF1C4" /></linearGradient>
          <clipPath id="janela"><rect x={430} y={150} width={1060} height={690} rx={14} /></clipPath>
        </defs>
        <g filter="url(#trem)">{(PLANOS[P.s.t] || PTexto)(ctx)}</g>
        {lf < 3 && P.i > 0 && <rect width={1920} height={1080} fill="#fff" opacity={(3 - lf) * 0.05} />}
        <rect width={1920} height={1080} filter="url(#grao)" style={{ mixBlendMode: 'multiply' }} />
        <rect width={1920} height={1080} fill="url(#vinh)" />
        {saldo != null && hudK > 0 && !SEM_HUD.includes(P.s.t) && <Extrato valor={saldo} k={hudK} pulso={hudPulso} />}
        {f < 8 && <rect width={1920} height={1080} fill="#000" opacity={1 - f / 8} />}
        {f > total - 14 && <rect width={1920} height={1080} fill="#000" opacity={(f - (total - 14)) / 14} />}
      </svg>
    </AbsoluteFill>);
};
